#include <bits/stdc++.h>
using namespace std;

bool hasCycle(ListNode *head) {
    unordered_set<ListNode*> visited;                                           // remember every node pointer seen so far
    ListNode *node = head;
    while (node) {
        if (visited.count(node)) return true;                                    // revisiting a node means a cycle exists
        visited.insert(node);
        node = node->next;
    }
    return false;
}

int main() {
    ListNode *n1 = new ListNode(3);
    ListNode *n2 = new ListNode(2);
    ListNode *n3 = new ListNode(0);
    ListNode *n4 = new ListNode(-4);
    n1->next = n2; n2->next = n3; n3->next = n4; n4->next = n2;
    cout << (hasCycle(n1) ? "true" : "false") << endl;
    return 0;
}

